// Playable maps. Lake Country and Holy Hill are real places (OpenStreetMap roads +
// USGS terrain) with fictional garages and venues; Ironport is a fictional city
// generated by scripts/build-ironport.mjs. Each has its own events, police posts and
// styling. One map is active per page load; switching saves the choice and reloads.
import { useEvents } from '../events/defs';
import { usePlaces } from './places';

export type MapId = 'lakecountry' | 'holyhill' | 'ironport' | 'hollowpeak';

export interface MapDef {
  id: MapId;
  /** Event records (medals, bests, ghosts) belong to one map version. */
  saveId: string;
  file: string;
  name: string;
  logo: string;
  tagline: string;
  /** Short line for the map picker. */
  blurb: string;
  loading: string;
  /** Fallback area name on the HUD. */
  region: string;
  /** Landmark that marks a downtown (curbs, storefront density), if any. */
  downtownLandmark: string | null;
  downtownName: string;
  /** Villages whose streets get curbs, sidewalks and streetlights. */
  townVillages: string[];
  /** Wooded by default: listed villages, or the whole map. */
  woodedVillages: string[] | 'all';
  /** "Welcome to" signs on main roads entering these villages. */
  welcomeSigns: { name: string; est: string; bg: string }[];
  /** Posted radar units: freeway name (median posts) and main-road classes. */
  postedFreeway: string | null;
  postedRoads: string[];
  postedSpacing: number;
  /** Landmarks shown on the full map (real ones, or the city's own on Ironport). */
  mapLandmarks: string[];
  /** A generated city: sidewalks everywhere, overhead lights, no trees or lamp posts. */
  city?: boolean;
  /** Police presence: patrols in traffic, extra units per heat level, and whether any officer who sees you starts a chase. */
  cops?: { patrols: number; extraUnits: number; wantedOnSight: boolean; force?: 'warden' };
  /** Keep trees this far (m) back from the speedways. */
  treeClear?: number;
  /** Map credit line (real maps credit OpenStreetMap and USGS). */
  credits?: string;
}

