export let MAP: MapDef = MAPS.lakecountry;

export function isMapId(id: unknown): id is MapId {
  return typeof id === 'string' && id in MAPS;
}

/** Make a map active: its events and venues become the ones every module sees. */
export function selectMap(id: MapId) {
  MAP = MAPS[id];
  useEvents(id);
  usePlaces(id);
  return MAP;
}

const CHOICE_KEY = 'lake-country/map';

/** Which map to load: ?map= in the URL, else the last one played. */
export function chosenMap(): MapId {
  try {
    const q = new URLSearchParams(location.search).get('map');
    if (isMapId(q)) return q;
    const s = localStorage.getItem(CHOICE_KEY);
    if (isMapId(s)) return s;
  } catch {
    /* storage blocked */
  }
  return 'lakecountry';
}

/** Remember the map for the next load; false when storage is blocked. */
export function rememberMap(id: MapId) {
  try {
    localStorage.setItem(CHOICE_KEY, id);
    return localStorage.getItem(CHOICE_KEY) === id;
  } catch {
    return false;
  }
}
